import { existsSync, readFileSync } from 'node:fs';
import path from 'node:path';

/**
 * Connector API keys the dev server may publish to the app, read from the repo-root `.env`
 * (generated by `op inject -i .env.tpl -o .env`).
 *
 * An explicit allowlist rather than "every variable in `.env`": that file holds Cloudflare, AWS
 * and GitHub credentials that no browser should ever see, and an allowlist makes the exposed set
 * greppable. Each name must match the `envBinding` a connector declares — see
 * `ConnectorSpec.ConnectorEntry.envBinding`.
 */
const EXPOSED = ['HEYGEN_API_KEY', 'IDEOGRAM_API_KEY'] as const;

const parseEnvFile = (file: string): Map<string, string> => {
  const values = new Map<string, string>();
  for (const line of readFileSync(file, 'utf8').split('\n')) {
    const match = /^\s*(?:export\s+)?([A-Z0-9_]+)\s*=(.*)$/.exec(line);
    if (match) {
      values.set(match[1], match[2].trim().replace(/^["']|["']$/g, ''));
    }
  }
  return values;
};

/**
 * `define` entries publishing the allowlisted keys as `import.meta.env.DX_SECRET_<NAME>`, so
 * plugin-connector can provision connections on startup instead of the user pasting a key into a
 * dialog after every profile reset.
 *
 * **Returns nothing unless `command === 'serve'`.** The values are inlined at transform time, so
 * a production bundle would ship them to anyone who loads the page; gating on the command means
 * the guarantee is structural rather than a runtime flag someone can flip. Values still only
 * reach a browser on localhost, which is why the allowlist above stays narrow.
 */
export const devSecrets = (command: string, rootDir: string): Record<string, string> => {
  if (command !== 'serve') {
    return {};
  }
  const file = path.resolve(rootDir, '.env');
  if (!existsSync(file)) {
    return {};
  }

  const values = parseEnvFile(file);
  const define: Record<string, string> = {};
  const published: string[] = [];
  for (const name of EXPOSED) {
    const value = values.get(name);
    if (value) {
      define[`import.meta.env.DX_SECRET_${name}`] = JSON.stringify(value);
      published.push(name);
    }
  }
  // `define` substitutes textually, so the app cannot enumerate `import.meta.env` for these —
  // this list is how plugin-connector knows whether there is anything to provision at all.
  define['import.meta.env.DX_SECRET_NAMES'] = JSON.stringify(published.join(','));
  return define;
};
